import type {LoaderFunctionArgs} from 'react-router';
import {useLoaderData} from 'react-router';
const QUERY=`#graphql\nquery Product($handle:String!){product(handle:$handle){id title descriptionHtml featuredImage{url altText} variants(first:20){nodes{id title price{amount currencyCode} availableForSale}}}}`;
export async function loader({params,context}:LoaderFunctionArgs){const data=await context.storefront.query(QUERY,{variables:{handle:params.handle}}); if(!data?.product) throw new Response('Not Found',{status:404}); return {product:data.product};}
export default function Product(){const {product}=useLoaderData<typeof loader>(); const v=product.variants.nodes[0]; return <main className="product-page"><div className="product-visual">{product.featuredImage&&<img src={product.featuredImage.url} alt={product.featuredImage.altText||product.title}/>}</div><div className="product-info"><p className="eyebrow">PRODUCT / INTERACTIVE</p><h1>{product.title}</h1><div className="product-description" dangerouslySetInnerHTML={{__html:product.descriptionHtml||''}}/><div className="price">{v?.price.currencyCode} {Number(v?.price.amount||0).toFixed(2)}</div><button className="button button-primary" disabled={!v?.availableForSale}>{v?.availableForSale?'Add to experience':'Unavailable'}</button></div></main>}
